const data = $input.first().json;

const formatDate = new Date(data.consultation_date)
  .toISOString()
  .slice(0, 10);

const symptoms = (data.symptoms || [])
  .map(s => {
    const symptomName = String(s.symptom || '').trim();

    return (
      `- [[${symptomName}]] (ID: ${s.symptom_id})\n` +
      `  - Evidence: ${s.evidence}\n` +
      `  - Certainty: ${s.certainty}`
    );
  })
  .join('\n');

const redFlags = (data.red_flags || [])
  .map(r =>
    `- **${r.symptom}** — ${r.reason}`
  )
  .join('\n');

const diseases = (data.disease_matches || [])
  .map(d => {
    const diseaseName = String(d.disease || '').trim();

    return `- [[${diseaseName}]] — ${d.matching_symptoms} matching symptoms`;
  })
  .join('\n');

const markdown = `# Clinical Consultation

## Consultation

- Consultation ID: ${data.consultation_id}
- Patient ID: ${data.patient_id}
- Date: ${formatDate}
- Language: ${data.language}

## Chief Complaint

${data.chief_complaint || 'Not specified'}

## Clinical Summary

${data.clinical_summary || 'Not specified'}

## Duration

${data.duration || 'Not specified'}

## Severity

${data.severity || 'Not specified'}

## Relevant History

${data.relevant_history || 'Not specified'}

## Symptoms

${symptoms || 'None recorded'}

## Emergency Assessment

- Emergency: **${data.emergency ? 'YES' : 'NO'}**
- Urgency: **${data.urgency || 'Not specified'}**

### Red Flags

${redFlags || 'None recorded'}

### Emergency Reason

${data.emergency_reason || 'Not specified'}

## Disease Matches

> These are dataset-based symptom matches and are **not a medical diagnosis**.

${diseases || 'None recorded'}

## Original Transcript

${data.transcript || 'Not available'}
`;

return [
  {
    json: {
      ...data,
      obsidian_filename: `${formatDate}-${data.consultation_id}.md`,
      obsidian_markdown: markdown
    }
  }
];
